SELECT opw.main_id, opw.platform_warehouse_code, opw.platform_warehouse_name, opw.platform_warehouse_status, opw.country, opw.country_name, opw.warehouse_id, opw.warehouse_name, opw.warehouse_code, opw.disabled, op.code AS providerCode, op.name AS providerName, op.owner_code as ownerCode FROM overseas_provider_warehouse opw INNER JOIN overseas_provider op ON op.id = opw.main_id and op.is_deleted=false WHERE opw.is_deleted=false and opw.disabled = false and op.auth_status = 'already'
AND opw.warehouse_id IN
#{item}
